function Numerique(s)
{
	let chiffre="0123456789";
	num=true;
	let i=0
	do
		{
			var car=s[i];
			if(chiffre.indexOf(car)==-1)
				{
					num=false;
					break;
				}
			i++;
		}while((i<s.length)&&(num==true));
	
	return num;
}
function Aphabetique(s) {
  let i = 0;
  let s=s.toUpperCase();
  let alph = true;
  do {
    if (s[i] < "A" || s[i] > "Z") {
      alph = false;
    }
    i++;
  } while (i < s.length && alph == true);
  return alph;
}
function Alphanumerique(s) {
  let s=s.toUpperCase();
  let alphnum = true;
  for (var i = 0; i < s.length; i++) {
    if (
      !(s[i] >= "0" && s[i]<= "9") &&
      !(s[i] >= "A" && s[i] <= "Z")
    )
      alphnum = false;
  }
  return alphnum;
}

